package factory.fun;
import android.app.Activity;
import android.os.Bundle;
import android.content.SharedPreferences;
import android.content.Context;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import java.util.*;
public final class MainActivity extends Activity {

 private LinearLayout root;private ScrollView scroll;private TextView status;private SharedPreferences prefs;
 private String t(String en,String ko,String ja){String l=getResources().getConfiguration().getLocales().get(0).getLanguage();return "ko".equals(l)?ko:"ja".equals(l)?ja:en;}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void setup(String intro){prefs=getSharedPreferences("local",MODE_PRIVATE);scroll=new ScrollView(this);scroll.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(20),dp(16),dp(20),dp(28));scroll.addView(root);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(a.left,a.top,a.right,a.bottom);return i;});TextView title=label(getString(R.string.app_name));title.setTextSize(32);title.setTypeface(null,Typeface.BOLD);label(intro);status=label(t("Ready","준비 완료","準備完了"));status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}
 private TextView label(String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(17);v.setPadding(0,dp(8),0,dp(8));root.addView(v);return v;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setMinHeight(dp(48));b.setOnClickListener(v->action.run());root.addView(b);return b;}
 private EditText edit(String name,String value){label(name);EditText e=new EditText(this);e.setContentDescription(name);e.setText(value);root.addView(e);return e;}
 private Spinner options(String title,String... items){label(title);Spinner s=new Spinner(this);s.setContentDescription(title);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items));root.addView(s);return s;}
 private void change(Spinner s,Runnable r){s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){r.run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});}

 private Banner preview,full;private EditText message;private Spinner colors,directions;private SeekBar speed,size;private boolean expanded;
 @Override public void onCreate(Bundle state){super.onCreate(state);setup(t("Make a moving sign for concerts, pickups or greetings.","공연 응원, 마중, 인사에 사용할 전광판을 만드세요.","応援・お迎え・挨拶の電光掲示板を作成。"));message=edit(t("Message","문구","メッセージ"),prefs.getString("message","HELLO!"));message.setSingleLine(true);message.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(120)});colors=options(t("Text color","글자 색상","文字色"),t("Yellow","노랑","黄色"),t("White","흰색","白"),t("Cyan","하늘색","水色"),t("Pink","분홍","ピンク"),t("Green","초록","緑"));directions=options(t("Motion","이동","動き"),t("Left","왼쪽","左"),t("Right","오른쪽","右"),t("Static","고정","固定"));label(t("Speed","속도","速度"));speed=new SeekBar(this);speed.setMax(9);speed.setProgress(4);speed.setContentDescription(t("Speed","속도","速度"));root.addView(speed);label(t("Text size","글자 크기","文字サイズ"));size=new SeekBar(this);size.setMax(8);size.setProgress(4);size.setContentDescription(t("Text size","글자 크기","文字サイズ"));root.addView(size);preview=new Banner(this);root.addView(preview,new LinearLayout.LayoutParams(-1,dp(150)));button(t("Apply and save","적용 및 저장","適用・保存"),()->{if(apply())status.setText(t("Applied","적용 완료","適用済み"));});button(t("Fullscreen (tap to exit)","전체 화면 (탭하면 종료)","全画面（タップで終了）"),()->{if(!apply())return;full=new Banner(this);full.setOnClickListener(v->closeFull());full.setContentDescription(t("Tap to leave fullscreen","탭하여 전체 화면 종료","タップで全画面終了"));expanded=true;setContentView(full);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);WindowInsetsController c=getWindow().getInsetsController();if(c!=null){c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);c.hide(WindowInsets.Type.systemBars());}});colors.setSelection(Math.max(0,Math.min(4,prefs.getInt("color",0))));directions.setSelection(Math.max(0,Math.min(2,prefs.getInt("direction",0))));speed.setProgress(prefs.getInt("speed",4));size.setProgress(prefs.getInt("size",4));apply();}
 private String text="HELLO!";private int color=Color.YELLOW,dir=0,rate=5,font=4;
 private boolean apply(){String s=message.getText().toString().trim();if(s.isEmpty()){status.setText(t("Enter a message","문구를 입력하세요","メッセージを入力してください"));return false;}text=s;color=new int[]{Color.YELLOW,Color.WHITE,Color.CYAN,0xffff69b4,0xff66ff66}[colors.getSelectedItemPosition()];dir=directions.getSelectedItemPosition();rate=speed.getProgress()+1;font=size.getProgress();prefs.edit().putString("message",s).putInt("color",colors.getSelectedItemPosition()).putInt("direction",dir).putInt("speed",rate-1).putInt("size",font).apply();preview.setContentDescription(s);preview.invalidate();return true;}
 private void closeFull(){if(!expanded)return;expanded=false;getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);WindowInsetsController c=getWindow().getInsetsController();if(c!=null)c.show(WindowInsets.Type.systemBars());setContentView(scroll);full=null;}
 @Override public void onBackPressed(){if(expanded)closeFull();else super.onBackPressed();}
 private class Banner extends View{private Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private long start=android.os.SystemClock.uptimeMillis();Banner(Context c){super(c);}protected void onDraw(Canvas c){c.drawColor(Color.BLACK);p.setColor(color);p.setTypeface(Typeface.create("sans-serif-condensed",Typeface.BOLD));p.setTextSize(Math.max(12,getHeight()*(.25f+.075f*font)));float width=p.measureText(text);if(dir==2&&width>getWidth()-dp(12)){p.setTextSize(p.getTextSize()*(getWidth()-dp(12))/width);width=p.measureText(text);}float x=Rules.position(getWidth(),width,dir,(android.os.SystemClock.uptimeMillis()-start)/1000f*dp(rate*24));float y=getHeight()/2f-(p.ascent()+p.descent())/2f;c.drawText(text,x,y,p);if(dir!=2&&isShown())postInvalidateOnAnimation();}}

}
